void mainCRTStartup(void){int ac;WCHAR**av=CommandLineToArgvW(GetCommandLineW(),&ac);if(ac!=9)ExitProcess(2);DWORD pid=(DWORD)parse(av[2]),tid=(DWORD)parse(av[3]);HWND hwnd=(HWND)(ULONG_PTR)parse(av[4]);DWORD owner=0;DWORD actual=GetWindowThreadProcessId(hwnd,&owner);if(owner!=pid||actual!=tid)ExitProcess(3);HMODULE dll=LoadLibraryW(av[1]);if(!dll)ExitProcess(4);HOOKPROC cb=(HOOKPROC)GetProcAddress(dll,"AtlasIdentityProbe");if(!cb){FreeLibrary(dll);ExitProcess(5);}UINT msg=RegisterWindowMessageW(av[5]);if(!msg){FreeLibrary(dll);ExitProcess(6);}ULONGLONG start=GetTickCount64();HHOOK hook=SetWindowsHookExW(WH_GETMESSAGE,cb,dll,tid);DWORD hookError=hook?0:GetLastError();BOOL posted=FALSE,removed=FALSE;DWORD postError=0,removeError=0;if(hook){posted=PostMessageW(hwnd,msg,(WPARAM)parse(av[6]),(LPARAM)parse(av[7]));postError=posted?0:GetLastError();if(posted)Sleep(1500);removed=UnhookWindowsHookEx(hook);removeError=removed?0:GetLastError();}ULONGLONG elapsed=GetTickCount64()-start;add("{\"installed\":");add(hook?"true":"false");add(",\"installError\":");num(hookError);add(",\"postedUniqueNonInputMessage\":");add(posted?"true":"false");add(",\"postError\":");num(postError);add(",\"unhooked\":");add(removed?"true":"false");add(",\"unhookError\":");num(removeError);add(",\"elapsedMilliseconds\":");num(elapsed);add("}\n");BOOL saved=save(av[8]);if(removed||!hook)FreeLibrary(dll);ExitProcess(saved&&hook&&posted&&removed&&elapsed<5000?0:10);}
